    // Verify JWT token
    const { payload } = await jwtVerify(token, JWT_SECRET);

    // Return user info
    return NextResponse.json({
      authenticated: true,
      user: {
        id: payload.sub,
        email: payload.email,
        role: payload.role,
        exp: payload.exp,
      },
      location: {
        country: request.geo?.country,
        city: request.geo?.city,
      },
    });

  } catch (error) {
